function findOccurrences(t, keyword) {
  let idx = 0;
  const results = [];
  while ((idx = t.toLowerCase().indexOf(keyword.toLowerCase(), idx)) !== -1) {
    results.push(t.slice(Math.max(0, idx - 100), Math.min(t.length, idx + 100)));
    idx += keyword.length;
  }
  return results;
}

