args.code:
const res = await tool.fetch_url({ url: "https://support.ouraring.com/hc/sitemap.xml" });
const xml = res.body;
const regex = /<loc>(https:\/\/support\.ouraring\.com\/hc\/en-us\/articles\/[^<]+)<\/loc>/g;
const urls = [];
let m;
while ((m = regex.exec(xml)) !== null) {
  urls.push(m[1]);
}

console.log("Searching among", urls.length, "articles...");
// Let's search candidates that might be relevant
const candidates = urls.filter(u => {
  const l = u.toLowerCase();
  return l.includes("privacy") || l.includes("ai") || l.includes("advisor") || l.includes("member") || l.includes("data") || l.includes("account") || l.includes("contact") || l.includes("care") || l.includes("settings") || l.includes("security");
});

console.log("Candidate count:", candidates.length);
const matches = [];

for (const url of candidates) {
  try {
    const r = await tool.fetch_url({ url });
    const text = r.body;
    if (text.includes("Finn") || text.includes("agent") || text.includes("Advisor") || text.includes("AI")) {
      matches.push({
        url,
        hasFinn: text.includes("Finn"),
        hasAgent: text.includes("agent"),
        hasAdvisor: text.includes("Advisor"),
        hasAI: text.includes("AI")
      });
    }
  } catch (e) {
    // ignore
  }
}

