  const url = `https://docs.google.com/forms/d/e/${id}/viewform`;
  const res = await tool.fetch_url({ url });
  const m = res.body.match(/FB_PUBLIC_LOAD_DATA_\s*=\s*(\[.+?\]);\s*<\/script>/s);
  if (m) {
    try {
      const data = JSON.parse(m[1]);
      const title = data[1]?.[8];
      const desc = data[1]?.[0];
      const questions = (data[1]?.[1] || []).map(q => ({
        label: q[1],
        desc: q[2],
        options: q[4]?.[0]?.[1]?.map(opt => opt[0])
      }));
      console.log(`=== Form ${id} ===`);
      console.log("Title:", title);
      console.log("Desc:", desc);
      console.log("Questions count:", questions.length);
      for (const q of questions) {
        console.log(`  - ${q.label} (options: ${q.options?.join(', ') || 'none'})`);
      }
    } catch (e) {
      console.log(`Parse error for ${id}:`, e.message);
    }
  }
}

