const tabId = 103795342;
// Check link for audio challenge
const audioLink = await browserjs(tabId, () => {
  const a = document.querySelector('a[href*="audio"], a[href*="payload"]');
  return a ? a.href : null;
});
console.log("Audio link:", audioLink);

// Also let's search Startpage on another tab (tab 103795220) for Norton Secure VPN official page
await tool.navigate({ tabId: 103795220, url: "https://www.startpage.com/sp/search?query=Norton+Secure+VPN+official+product+page" });
await tool.wait_for({ tabId: 103795220, condition: "load_state", value: "load" });

const results = await browserjs(103795220, () => {
  const items = Array.from(document.querySelectorAll('.result, .w-gl__result, [class*="result"]'));
  return items.map(el => {
    const a = el.querySelector('a');
    return {
      title: el.querySelector('h2, h3, .title')?.textContent?.trim(),
      snippet: el.textContent?.trim()?.slice(0, 200),
      href: a?.href
    };
  }).filter(r => r.title);
});

console.log("Norton search results from Startpage:");
for (const r of results.slice(0, 5)) {
  console.log(`- ${r.title} | ${r.href}`);
}

